// 定义引脚
#define CLK 2
#define DT  3

int counter = 0;  // 旋转次数
unsigned long currentTime = 0;
unsigned long lastTime = 0;

void setup() {
  pinMode(CLK, INPUT);
  pinMode(DT, INPUT);

  // 使用中断
  attachInterrupt(0, UpdateCounter, RISING); // 对应引脚2

  Serial.begin(9600);
}

void loop() {

}

void UpdateCounter(){
  currentTime = millis();
  if(currentTime - lastTime > 10){  // 防抖动
    int CLKState = digitalRead(CLK);
    // 当CLK更改状态时：
    // 如果DT != CLK，顺时针旋转
    // 如果DT == CLK, 逆时针旋转
    if(digitalRead(DT) != CLKState){
      counter ++;
    }
    else{
      counter --;
    }
    lastTime = currentTime;

    Serial.print("counter: ");
    Serial.println(counter);
  }
}

// 定义传感器引脚
int sensorPin = 2;
// 定义LED引脚
int ledPin = 13;
// 定义变量来保存传感器的状态
int sensorState = 0;

void setup() {
    // 将LED引脚设置为输出模式
    pinMode(ledPin, OUTPUT);
    // 将传感器引脚设置为输入模式
    pinMode(sensorPin, INPUT);
    // 开启串口通信
    Serial.begin(9600);
}

void loop() {
    // 读取传感器状态
    sensorState = digitalRead(sensorPin);

    if (sensorState == HIGH) {
        // 当有人存在时，点亮LED并打印信息
        digitalWrite(ledPin, HIGH);
        Serial.println("Detected human presence");
    } else {
        // 当无人存在时，熄灭LED
        digitalWrite(ledPin, LOW);
    }

    // 延迟一段时间后重新执行循环
    delay(1000);
}

#include <WiFi.h>
#include <HTTPClient.h>

const char* ssid = "your_SSID";
const char* password = "your_PASSWORD";

void setup() {
  Serial.begin(115200);
  delay(1000);

  WiFi.begin(ssid, password);

  while (WiFi.status() != WL_CONNECTED) {
    delay(1000);
    Serial.println("Connecting to WiFi...");
  }

  Serial.println("WiFi connected");
}

void loop() {
  if (WiFi.status() == WL_CONNECTED) {
    HTTPClient http;
    http.begin("http://api.openweathermap.org/data/2.5/weather?q=Shenzhen&appid=your_API_key");

    int httpCode = http.GET();

    if (httpCode > 0) {
      String payload = http.getString();
      Serial.println(payload);
    }

    http.end();
  }

  delay(60000); // 每隔一分钟获取一次天气 API
}

#include <FastLED.h>

#define LED_PIN 7 // LED引脚
#define NUM_LEDS 60 // 灯珠数量

CRGB leds[NUM_LEDS];
int hour = 0;
int min = 0;
int sec = 0;

void setup() {
  FastLED.addLeds<WS2812, LED_PIN, GRB>(leds, NUM_LEDS); // 初始化灯带
}

void loop() {
  EVERY_N_SECONDS(1){ // 每隔1秒定时执行
    Timing();
    UpdateLEDS();
  }
}

void Timing(){
  sec ++;
  if(sec >= 60){
    sec -= 60;
    min ++;
    if(min >= 60){
      min -= 60;
      hour ++;
    }
    if(hour >= 12){
      hour -= 12;
    }
  }
}

void UpdateLEDS(){
  leds[sec] = CRGB(0, 0, 255);
  leds[min] = CRGB(0, 255, 0);
  leds[(hour + min / 60) * 5] = CRGB(255, 0, 0);
}
